s=s.replace(needle,'// Whole-island outline. Own layers only: never alter Apple\'s frame, bounds, mask or corner radius.\nstatic BOOL RSHaloEnabled=YES;\nstatic BOOL RSHaloShadow=YES;\nstatic CGFloat RSHaloWidth=1.5;\nstatic NSInteger RSHaloColorIndex=1;\nstatic NSUInteger RSHaloConfigVersion=0;\nstatic BOOL RSHaloPrefsLoaded=NO;\nstatic NSHashTable *RSHaloHosts=nil;\nstatic BOOL RSHaloBool(CFStringRef key,BOOL fallback) {\n    CFPropertyListRef raw=RSCopyPreference(key);if(!raw)return fallback;\n    BOOL value=fallback;\n    if(CFGetTypeID(raw)==CFBooleanGetTypeID())value=CFBooleanGetValue((CFBooleanRef)raw);\n    else if(CFGetTypeID(raw)==CFNumberGetTypeID()){int n=0;CFNumberGetValue((CFNumberRef)raw,kCFNumberIntType,&n);value=n!=0;}\n    CFRelease(raw);return value;\n}\nstatic void RSHaloLoadPreferences(void) {\n    RSHaloEnabled=RSHaloBool(CFSTR("islandHaloEnabled"),YES);\n    RSHaloShadow=RSHaloBool(CFSTR("islandHaloShadow"),YES);\n    RSHaloWidth=RSFloatPreference(CFSTR("islandHaloWidth"),1.5,0.5,5.0);\n    RSHaloColorIndex=(NSInteger)RSFloatPreference(CFSTR("islandHaloColor"),1,0,5);\n    RSHaloPrefsLoaded=YES;RSHaloConfigVersion++;\n}\nstatic UIColor *RSHaloColor(void) {\n    switch(RSHaloColorIndex){\n        case 0:return [UIColor colorWithRed:1.0 green:0.16 blue:0.22 alpha:1];\n        case 2:return [UIColor colorWithRed:0.72 green:0.32 blue:1.0 alpha:1];\n        case 3:return [UIColor colorWithRed:0.18 green:1.0 blue:0.45 alpha:1];\n        case 4:return [UIColor colorWithRed:1.0 green:0.76 blue:0.15 alpha:1];\n        case 5:return UIColor.whiteColor;\n        default:return [UIColor colorWithRed:0.12 green:0.65 blue:1.0 alpha:1];\n    }\n}\nstatic BOOL RSHaloIsContainer(UIView *view) {\n    NSString *name=NSStringFromClass(view.class);\n    return [name isEqualToString:@"SBSystemApertureContainerView"];\n}\nstatic BOOL RSHaloValidBounds(CGRect bounds,UIWindow *window) {\n    CGFloat w=CGRectGetWidth(bounds),h=CGRectGetHeight(bounds);\n    return window && isfinite(w) && isfinite(h) && w>=90 && h>=20 && h<=240 && w<=CGRectGetWidth(window.bounds)-8;\n}\n@interface RSIslandHaloState : NSObject\n@property(nonatomic,weak) UIView *host;\n@property(nonatomic,strong) CAShapeLayer *outline;\n@property(nonatomic,strong) CADisplayLink *displayLink;\n@property(nonatomic,assign) CGRect lastRect;\n@property(nonatomic,assign) CGFloat lastRadius;\n@property(nonatomic,assign) NSUInteger configVersion;\n@property(nonatomic,assign) BOOL updating;\n@property(nonatomic,assign) CFTimeInterval animationDeadline;\n- (void)update;\n- (void)stop;\n@end\n@implementation RSIslandHaloState\n- (void)dealloc {[_displayLink invalidate];}\n- (void)stop { [self.displayLink invalidate];self.displayLink=nil; }\n- (void)tick:(CADisplayLink *)link { [self update]; }\n- (void)update {\n    if(self.updating)return;\n    self.updating=YES;\n    @try {\n        UIView *host=self.host;\n        if(!host || !host.window || host.hidden || host.alpha<0.01 || !RSHaloEnabled || !RSIsEnabled() || !RSHaloValidBounds(host.bounds,host.window)){\n            self.outline.hidden=YES;[self stop];return;\n        }\n        // Only one outline if a future OS nests equivalent island containers.\n        for(UIView *ancestor=host.superview;ancestor && ancestor!=host.window;ancestor=ancestor.superview){\n            if(RSHaloIsContainer(ancestor) && RSHaloValidBounds(ancestor.bounds,ancestor.window)){\n                self.outline.hidden=YES;[self stop];return;\n            }\n        }\n        CALayer *presentation=(CALayer *)host.layer.presentationLayer;\n        CGRect actual=(presentation && !CGRectIsEmpty(presentation.bounds)) ? presentation.bounds : host.bounds;\n        if(!RSHaloValidBounds(actual,host.window))actual=host.bounds;\n        CGFloat nativeRadius=presentation ? presentation.cornerRadius : host.layer.cornerRadius;\n        CGFloat half=MIN(CGRectGetWidth(actual),CGRectGetHeight(actual))*0.5;\n        CGFloat radius=nativeRadius>0 ? MIN(nativeRadius,half) : half;\n        BOOL moving=presentation && (fabs(CGRectGetWidth(presentation.bounds)-CGRectGetWidth(host.bounds))>0.1 || fabs(CGRectGetHeight(presentation.bounds)-CGRectGetHeight(host.bounds))>0.1 || fabs(presentation.cornerRadius-host.layer.cornerRadius)>0.1);\n        if(!self.outline){\n            CAShapeLayer *line=[CAShapeLayer layer];line.name=@"RecordingSharingan.WholeIslandHalo";\n            line.fillColor=UIColor.clearColor.CGColor;line.lineJoin=kCALineJoinRound;\n            line.zPosition=10000;line.contentsScale=host.window.screen.scale;\n            self.outline=line;\n        }\n        if(self.outline.superlayer!=host.layer)[host.layer addSublayer:self.outline];\n        BOOL geometryChanged=!CGRectEqualToRect(actual,self.lastRect) || fabs(radius-self.lastRadius)>0.01;\n        BOOL configChanged=self.configVersion!=RSHaloConfigVersion;\n        [CATransaction begin];[CATransaction setDisableActions:YES];\n        self.outline.hidden=NO;\n        if(geometryChanged || configChanged || !self.outline.path){\n            CGFloat inset=RSHaloWidth*0.5+0.25;\n            CGRect local=CGRectInset(CGRectMake(0,0,CGRectGetWidth(actual),CGRectGetHeight(actual)),inset,inset);\n            UIBezierPath *path=[UIBezierPath bezierPathWithRoundedRect:local cornerRadius:MAX(0,radius-inset)];\n            self.outline.frame=actual;self.outline.path=path.CGPath;\n            self.outline.lineWidth=RSHaloWidth;\n            UIColor *color=RSHaloColor();self.outline.strokeColor=color.CGColor;\n            self.outline.shadowColor=color.CGColor;self.outline.shadowOffset=CGSizeZero;\n            self.outline.shadowRadius=4.0;self.outline.shadowOpacity=RSHaloShadow ? 0.85 : 0;\n            self.lastRect=actual;self.lastRadius=radius;self.configVersion=RSHaloConfigVersion;\n        }\n        [CATransaction commit];\n        if(moving){\n            // The link exists only during a geometry animation; never run an idle 60Hz timer.\n            if(!self.displayLink){\n                self.animationDeadline=CACurrentMediaTime()+2.0;\n                self.displayLink=[CADisplayLink displayLinkWithTarget:self selector:@selector(tick:)];\n                self.displayLink.preferredFramesPerSecond=60;\n                [self.displayLink addToRunLoop:NSRunLoop.mainRunLoop forMode:NSRunLoopCommonModes];\n            }else if(CACurrentMediaTime()>self.animationDeadline)[self stop];\n        }else [self stop];\n    } @catch(NSException *exception){\n        self.outline.hidden=YES;[self stop];RSLog(@"island halo exception: %@",exception);\n    } @finally { self.updating=NO; }\n}\n@end\nstatic char RSHaloStateKey;\nstatic void RSHaloTrackContainer(UIView *host) {\n    if(!NSThread.isMainThread || !RSHaloIsContainer(host))return;\n    if(!RSHaloPrefsLoaded)RSHaloLoadPreferences();\n    RSIslandHaloState *state=objc_getAssociatedObject(host,&RSHaloStateKey);\n    if(!state){\n        if(!RSHaloEnabled || !host.window || !RSHaloValidBounds(host.bounds,host.window))return;\n        state=[RSIslandHaloState new];state.host=host;state.lastRect=CGRectNull;\n        objc_setAssociatedObject(host,&RSHaloStateKey,state,OBJC_ASSOCIATION_RETAIN_NONATOMIC);\n        if(!RSHaloHosts)RSHaloHosts=[NSHashTable weakObjectsHashTable];\n        [RSHaloHosts addObject:host];\n        RSLog(@"whole-island halo attached host=%@ bounds=%@ radius=%.2f",NSStringFromClass(host.class),NSStringFromCGRect(host.bounds),host.layer.cornerRadius);\n    }\n    [state update];\n}\nstatic void RSHaloRefreshAll(void) {\n    RSHaloLoadPreferences();\n    for(UIView *host in RSHaloHosts.allObjects)RSHaloTrackContainer(host);\n    if(!RSHaloEnabled || !RSIsEnabled())return;\n    // Discovery is event-driven (launch/settings only), never a layout-time hierarchy scan.\n    for(UIWindow *window in RSAllApplicationWindows()){\n        NSMutableArray *stack=[NSMutableArray arrayWithObject:window];NSUInteger visited=0;\n        while(stack.count && visited++<3000){\n            UIView *view=stack.lastObject;[stack removeLastObject];\n            if(RSHaloIsContainer(view))RSHaloTrackContainer(view);\n            [stack addObjectsFromArray:view.subviews];\n        }\n    }\n}\n'+'\n'+needle,1)
